def transform(grid):
    from collections import Counter

    h, w = len(grid), len(grid[0])
    base = Counter(x for row in grid for x in row).most_common(1)[0][0]

    # Separator lines are the rows and columns containing little of the
    # repeated background color.
    rs = [r for r in range(h) if sum(v == base for v in grid[r]) < w / 2]
    cs = [c for c in range(w) if sum(grid[r][c] == base for r in range(h)) < h / 2]

    if len(rs) < 2 or len(cs) < 2:
        return [[grid[rs[0]][cs[0]] if rs and cs else base]]

    # The most common non-background color on the separator lines is the
    # ordinary separator color; other colors at crossings are marks.
    line_vals = []
    for r in rs:
        line_vals.extend(v for v in grid[r] if v != base)
    for c in cs:
        line_vals.extend(grid[r][c] for r in range(h) if grid[r][c] != base)
    line_color = Counter(line_vals).most_common(1)[0][0] if line_vals else base

    marks = [[grid[r][c] if grid[r][c] not in (base, line_color) else None
              for c in cs] for r in rs]

    # Ignore an unmarked partial outer line.
    while len(rs) > 2 and rs[0] > 0 and not any(marks[0]):
        rs.pop(0)
        marks.pop(0)
    while len(rs) > 2 and rs[-1] < h - 1 and not any(marks[-1]):
        rs.pop()
        marks.pop()
    while len(cs) > 2 and cs[0] > 0 and not any(row[0] for row in marks):
        cs.pop(0)
        for row in marks:
            row.pop(0)
    while len(cs) > 2 and cs[-1] < w - 1 and not any(row[-1] for row in marks):
        cs.pop()
        for row in marks:
            row.pop()

    out = [[base for _ in range(len(cs) - 1)] for _ in range(len(rs) - 1)]

    # A matching pair of marked crossings colors the cell alongside that
    # edge. Larger marked rectangles are handled by their adjacent pairs.
    for i in range(len(rs)):
        for j in range(len(cs) - 1):
            v = marks[i][j]
            if v is not None and marks[i][j + 1] == v and i < len(out):
                out[i][j] = v

    for i in range(len(rs) - 1):
        for j in range(len(cs)):
            v = marks[i][j]
            if v is not None and marks[i + 1][j] == v and j < len(out[0]):
                out[i][j] = v

    return out
