def transform(grid):
    from collections import Counter
    from math import gcd

    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    common = [v for v, _ in counts.most_common(2)]
    background = counts.most_common(1)[0][0]
    marked = set(counts) - set(common)

    marked_rows = [r for r in range(h)
                   if any(grid[r][c] in marked for c in range(w))]
    marked_cols = [c for c in range(w)
                   if any(grid[r][c] in marked for r in range(h))]

    def lattice(coords):
        if len(coords) < 2:
            return coords
        step = 0
        for a, b in zip(coords, coords[1:]):
            step = gcd(step, b - a)
        if step == 0:
            return coords
        return list(range(coords[0], coords[-1] + 1, step))

    rows = lattice(marked_rows)
    cols = lattice(marked_cols)
    if len(rows) < 2 or len(cols) < 2:
        return [[next(iter(marked), background)]]

    out = []
    for r1, r2 in zip(rows, rows[1:]):
        line = []
        for c1, c2 in zip(cols, cols[1:]):
            corners = [grid[r1][c1], grid[r1][c2],
                       grid[r2][c1], grid[r2][c2]]
            if corners[0] in marked and all(v == corners[0] for v in corners):
                line.append(corners[0])
            else:
                line.append(background)
        out.append(line)
    return out
